from urllib.parse import unquote
import re

def parse_query(query_string: str) -> dict:
    if not query_string:
        return {}

    query_string = query_string.lstrip('?')
    if not query_string:
        return {}

    result = {}
    pairs = query_string.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''

        key = unquote(key)
        value = unquote(value)

        # Bracket array: key[]
        if key.endswith('[]'):
            base_key = key[:-2]
            if base_key not in result:
                result[base_key] = []
            result[base_key].append(value)
        # Nested: key[sub]
        elif '[' in key and key.endswith(']'):
            match = re.match(r'^([^\[]+)\[([^\]]+)\]$', key)
            if match:
                base_key, sub_key = match.groups()
                if base_key not in result:
                    result[base_key] = {}
                result[base_key][sub_key] = value
        # Simple or duplicate
        else:
            if key in result:
                if isinstance(result[key], list):
                    result[key].append(value)
                else:
                    result[key] = [result[key], value]
            else:
                result[key] = value

    return result

def build_query(params: dict) -> str:
    pairs = []
    for key, value in params.items():
        if isinstance(value, list):
            for v in value:
                pairs.append(f'{key}[]={v}')
        elif isinstance(value, dict):
            for k, v in value.items():
                pairs.append(f'{key}[{k}]={v}')
        else:
            pairs.append(f'{key}={value}')
    return '&'.join(pairs)

