function parseQuery(queryString) {
  if (!queryString) return {};
  queryString = queryString.replace(/^\?/, '');
  if (!queryString) return {};

  const result = {};
  const pairs = queryString.split('&');

  for (const pair of pairs) {
    const eqIdx = pair.indexOf('=');
    let key = eqIdx === -1 ? decodeURIComponent(pair) : decodeURIComponent(pair.slice(0, eqIdx));
    const value = eqIdx === -1 ? '' : decodeURIComponent(pair.slice(eqIdx + 1));

    if (key.endsWith('[]')) {
      const baseKey = key.slice(0, -2);
      if (!result[baseKey]) result[baseKey] = [];
      result[baseKey].push(value);
    } else if (/^([^[]+)\[([^\]]+)\]$/.test(key)) {
      const [, baseKey, subKey] = key.match(/^([^[]+)\[([^\]]+)\]$/);
      if (!result[baseKey]) result[baseKey] = {};
      result[baseKey][subKey] = value;
    } else {
      if (key in result) {
        if (Array.isArray(result[key])) result[key].push(value);
        else result[key] = [result[key], value];
      } else {
        result[key] = value;
      }
    }
  }
  return result;
}

function buildQuery(params) {
  const pairs = [];
  for (const [key, value] of Object.entries(params)) {
    if (Array.isArray(value)) {
      value.forEach(v => pairs.push(`${key}[]=${v}`));
    } else if (typeof value === 'object' && value !== null) {
      Object.entries(value).forEach(([k, v]) => pairs.push(`${key}[${k}]=${v}`));
    } else {
      pairs.push(`${key}=${value}`);
    }
  }
  return pairs.join('&');
}
